mapper.select:
SELECT t.id AS id, c.name AS customerName, a.account_no AS accountNo, t.amount AS amount, t.type AS type, t.trans_time AS transTime FROM `transaction` t LEFT JOIN account a ON t.account_id = a.id LEFT JOIN customer c ON a.customer_id = c.id WHERE c.deleted = 0
AND t.type = #{type}
ORDER BY t.trans_time DESC LIMIT 20
